@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--ink:#101116;--paper:#e9dfc9;--muted:#a9a08e;--gold:#d8b874;--rust:#a95043;--line:rgba(222,198,150,.27)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101116;color:var(--paper);font-family:'DM Sans',sans-serif;touch-action:none}button{font:inherit;color:inherit}.game-shell{position:relative;width:100vw;height:100dvh;min-height:320px;overflow:hidden;background:#11141a;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;z-index:1;background:radial-gradient(ellipse at 52% 43%,transparent 34%,rgba(5,6,9,.2) 76%,rgba(4,5,8,.64) 140%),linear-gradient(180deg,rgba(8,10,14,.18),transparent 25%,transparent 70%,rgba(6,7,10,.4)}.screen{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;background:rgba(9,10,14,.48);backdrop-filter:blur(2px)}[hidden]{display:none!important}.title-screen{justify-content:space-between;overflow:hidden;background:linear-gradient(90deg,rgba(9,11,15,.98) 0%,rgba(9,11,15,.93) 38%,rgba(9,11,15,.2) 72%,rgba(9,11,15,.16) 100%)}.title-copy{position:relative;z-index:2;width:min(51%,670px);padding:4vh 0 7vh clamp(28px,9vw,150px)}.eyebrow{font-size:10px;letter-spacing:.28em;color:#c5a873;font-weight:700;margin:0 0 23px}.title-copy h1{font:500 clamp(54px,8.5vw,120px)/.9 'Cinzel',serif;letter-spacing:.045em;margin:0;color:#e8dfcb;text-shadow:0 3px 25px #000}.title-copy h1 em{font-style:normal;color:#c7a975}.rule{margin:26px 0 20px;width:min(260px,70%);height:1px;background:linear-gradient(90deg,#c7a975,transparent);position:relative}.rule i{position:absolute;left:45%;top:-10px;color:#d8b874;background:#121318;padding:0 9px;font-style:normal}.subtitle{font:italic 16px/1.65 'Cinzel',serif;color:#b9b09e;margin:0 0 31px}.primary-button{min-width:240px;padding:15px 19px;background:linear-gradient(135deg,#bd9658,#8e663e);border:1px solid rgba(255,235,191,.52);color:#17130f;font-size:10px;font-weight:700;letter-spacing:.16em;cursor:pointer;box-shadow:0 9px 30px #0007;transition:transform .18s,filter .18s}.primary-button span{float:right;font-size:16px;line-height:10px}.primary-button:hover{transform:translateY(-2px);filter:brightness(1.15)}.text-button{display:block;border:0;background:none;color:#bdb29a;font-size:9px;letter-spacing:.2em;padding:18px 0;cursor:pointer}.title-footer{position:absolute;bottom:2.5vh;font-size:8px;letter-spacing:.25em;color:#756d60}.title-hero{position:absolute;right:0;top:0;width:61%;height:100%;overflow:hidden;background:radial-gradient(ellipse at 57% 43%,#4a3733 0%,#28272a 24%,#17191e 52%,#111319 75%)}.title-hero:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#111319 0%,transparent 33%),radial-gradient(ellipse at 65% 60%,transparent 5%,rgba(8,9,13,.44) 73%)}.moon{position:absolute;left:44%;top:12%;width:clamp(110px,17vw,235px);aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 38% 36%,#eee0bd,#c3a879 52%,#665448 73%,transparent 75%);opacity:.73;box-shadow:0 0 90px #cfb47b28}.moon:after{content:'';position:absolute;inset:19%;border-radius:50%;background:radial-gradient(ellipse at 25% 63%,#83715d 0 7%,transparent 8%),radial-gradient(ellipse at 65% 29%,#8d7a63 0 5%,transparent 6%),radial-gradient(ellipse at 72% 70%,#8d7a63 0 9%,transparent 10%);opacity:.35}.hero-silhouette{position:absolute;left:49%;bottom:18%;height:43%;width:20%;transform:translateX(-20%);filter:drop-shadow(0 0 30px #dca45329)}.hero-silhouette:before{content:'';position:absolute;left:11%;bottom:0;width:79%;height:61%;background:linear-gradient(95deg,#17171a 0 32%,#292529 51%,#111318 80%);clip-path:polygon(25% 0,68% 0,90% 22%,83% 100%,15% 100%,4% 24%)}.hero-silhouette:after{content:'';position:absolute;left:21%;bottom:48%;width:57%;height:47%;background:radial-gradient(ellipse at 48% 18%,#343034 0 30%,transparent 32%),linear-gradient(110deg,#16171c,#403738 55%,#111319);clip-path:polygon(30% 0,73% 10%,100% 44%,81% 100%,11% 85%,0 39%)}.hero-silhouette i{position:absolute;z-index:2;width:7%;height:49%;bottom:21%;left:83%;background:linear-gradient(90deg,#5b4b40,#d2b37a 50%,#51483e);transform:rotate(-25deg);border-radius:60%}.hero-silhouette b{position:absolute;z-index:3;left:14%;bottom:53%;width:70%;height:8%;background:#27262a;clip-path:polygon(0 50%,100% 0,90% 100%)}.hero-silhouette em{position:absolute;z-index:2;left:42%;bottom:73%;width:22%;height:3%;background:#d6bd8b;box-shadow:0 0 12px #f1d594;transform:rotate(-25deg)}.title-ground{position:absolute;bottom:0;left:0;right:0;height:24%;background:linear-gradient(0deg,#101116 5%,#18181a 21%,transparent);clip-path:polygon(0 47%,12% 35%,22% 54%,35% 31%,49% 47%,62% 20%,74% 48%,88% 30%,100% 50%,100% 100%,0 100%)}.floating-ash{position:absolute;color:#dfc58e;text-shadow:0 0 8px #fff3;animation:drift 5s ease-in-out infinite}.ash-a{left:32%;top:53%;font-size:17px}.ash-b{left:69%;top:37%;animation-delay:-2s}.ash-c{left:78%;top:62%;font-size:13px;animation-delay:-3s}@keyframes drift{50%{transform:translate(8px,-14px);opacity:.35}}.title-controls{position:absolute;z-index:3;right:25px;bottom:22px;display:flex;gap:19px;color:#9e9689;font-size:8px;letter-spacing:.13em}.hud{position:absolute;z-index:3;inset:0 0 auto;min-height:85px;display:flex;align-items:center;padding:17px clamp(14px,4vw,54px);gap:20px;background:linear-gradient(180deg,rgba(8,10,14,.86),rgba(8,10,14,.24),transparent)}.brand-mark{display:flex;align-items:center;gap:10px;min-width:245px}.brand-icon{font-size:22px;color:#c9a76b}.brand-mark b{display:block;font:600 10px 'Cinzel',serif;letter-spacing:.15em}.brand-mark small{display:block;font-size:8px;letter-spacing:.2em;color:#a89c83;margin-top:4px}.vitals{width:clamp(150px,22vw,260px)}.hearts{display:flex;gap:4px;margin-bottom:8px}.heart{color:#c86858;font-size:17px;text-shadow:0 0 10px #d55d4777}.heart.empty{color:#514345;text-shadow:none}.soul-track{display:flex;align-items:center;gap:8px;font-size:7px;letter-spacing:.18em;color:#bbb19f}.soul-track>div,.boss-bar>div{height:5px;flex:1;background:#39363a;border:1px solid #6b5c53;overflow:hidden}.soul-track i,.boss-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#628d94,#a9d1c5);box-shadow:0 0 9px #8acbc0;transition:width .2s}.relic-count{margin-left:auto;color:#d9bd7d;display:flex;align-items:center;gap:5px}.relic-count span{font-size:19px}.relic-count b{font:16px 'Cinzel',serif}.relic-count small{font-size:10px;color:#928878}.icon-button{width:34px;height:34px;border:1px solid var(--line);background:#12141bd9;color:#d4c6a9;cursor:pointer;font-size:15px}.icon-button:hover{background:#7d6543}.boss-bar{position:absolute;z-index:3;top:94px;left:50%;transform:translateX(-50%);width:min(360px,60vw);font:10px 'Cinzel',serif;letter-spacing:.19em;text-align:center;color:#d5c7b1}.boss-bar>div{margin-top:7px;height:7px}.boss-bar i{background:linear-gradient(90deg,#933f3a,#df8260);box-shadow:0 0 9px #e15949}.toast{position:absolute;z-index:4;top:24%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#101116d9;border:1px solid var(--line);padding:11px 18px;font:italic 12px 'Cinzel',serif;color:#e0cca0;pointer-events:none;text-align:center}.toast.show{opacity:1;transform:translate(-50%,0)}.hint{position:absolute;z-index:3;bottom:25px;left:50%;transform:translateX(-50%);color:#c3b9a2;font-size:9px;letter-spacing:.12em;text-shadow:0 2px 6px #000;white-space:nowrap}.lore-screen,.pause-screen,.ending-screen{background:rgba(7,8,11,.77);backdrop-filter:blur(7px)}.lore-card,.pause-card,.ending-card{width:min(590px,88vw);max-height:88dvh;overflow:auto;padding:clamp(24px,5vw,53px);border:1px solid #97815b66;background:linear-gradient(145deg,#191a1eF5,#101115F7);box-shadow:0 25px 100px #000a;position:relative}.lore-card:before,.pause-card:before,.ending-card:before{content:'✦';position:absolute;top:14px;right:19px;color:#aa8d5c}.lore-card h2,.pause-card h2,.ending-card h2{font:500 clamp(30px,5vw,45px) 'Cinzel',serif;margin:0 0 20px;color:#e5d7bd}.lore-card p:not(.eyebrow),.pause-card p:not(.eyebrow),.ending-card p:not(.eyebrow){font-size:13px;line-height:1.9;color:#bcb4a7}.lore-card strong{color:#e2c48e;font-weight:500}.lore-quote{border-left:1px solid #ae8c5a;padding:7px 0 7px 16px;margin:22px 0 25px;color:#cdb98e;font:italic 13px/1.7 'Cinzel',serif}.pause-card,.ending-card{text-align:center}.pause-card .eyebrow,.ending-card .eyebrow{margin-bottom:18px}.pause-card .text-button{margin:auto}.touch-controls{display:none;position:absolute;z-index:4;inset:auto 0 max(18px,env(safe-area-inset-bottom)) 0;align-items:flex-end;justify-content:space-between;padding:0 18px;pointer-events:none}.touch-move,.touch-actions{display:flex;gap:9px;align-items:flex-end;pointer-events:auto}.touch-actions{gap:7px}.touch-controls button{width:clamp(47px,12vw,64px);height:clamp(47px,12vw,64px);border-radius:50%;border:1px solid #e8d7b355;background:#17171bbd;color:#e5d8bb;font-size:19px;box-shadow:0 5px 15px #0008;backdrop-filter:blur(4px);touch-action:none;user-select:none}.touch-controls .attack-touch{width:clamp(58px,15vw,76px);height:clamp(58px,15vw,76px);color:#e8bf7b;border-color:#deb77b88;font-size:24px}.touch-controls button.pressed{background:#85613e;color:#fff;transform:scale(.94)}
@media(max-width:700px){.title-screen{background:linear-gradient(90deg,rgba(8,10,13,.95),rgba(8,10,13,.56)),linear-gradient(0deg,#101116 0%,transparent 50%)}.title-copy{width:100%;padding:0 0 13vh 9vw;align-self:center}.title-copy h1{font-size:clamp(55px,14vw,92px)}.title-hero{width:100%;opacity:.64}.title-hero:before{background:linear-gradient(90deg,#11131955,transparent 80%),linear-gradient(0deg,#101116,transparent 48%)}.hero-silhouette{left:70%;height:38%;bottom:15%;width:26%}.moon{left:56%;top:16%;width:36vw}.title-controls{display:none}.title-footer{bottom:4vh}.subtitle{font-size:14px}.hud{min-height:69px;padding:11px 12px;gap:9px}.brand-mark{min-width:0;flex:1;gap:6px}.brand-icon{font-size:18px}.brand-mark b{font-size:8px;letter-spacing:.1em}.brand-mark small{font-size:6px;letter-spacing:.12em}.vitals{width:27vw}.hearts{gap:1px;margin-bottom:5px}.heart{font-size:14px}.soul-track{font-size:6px;gap:5px}.relic-count{gap:2px}.relic-count span{font-size:15px}.relic-count b{font-size:13px}.icon-button{width:30px;height:30px}.boss-bar{top:77px;font-size:8px}.touch-controls{display:flex}.hint{bottom:98px;font-size:8px}.lore-card{padding:27px 22px}.lore-card p:not(.eyebrow){font-size:12px;line-height:1.75}.eyebrow{font-size:8px}}
@media(hover:none) and (pointer:coarse){.touch-controls{display:flex}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const ui = Object.fromEntries(['hud','title-screen','lore-screen','pause-screen','ending-screen','hearts','soul-fill','relics','zone-name','toast','hint','boss-bar','boss-fill'].map(id => [id, document.getElementById(id)]));
  const keys = new Set();
  const actions = { left:false, right:false };
  const WORLD = 3300;
  let W = innerWidth, H = innerHeight, dpr = 1, floorY = H - 68, camera = 0;
  let mode = 'title', last = 0, elapsed = 0, toastTimer = 0, slashTimer = 0, slashHit = new Set(), shake = 0;
  let player, enemies, platforms, relics, particles, projectiles, boss, checkpoint, savedRelics;
  const rand = (seed) => { let t = seed + 0x6D2B79F5; t = Math.imul(t ^ t >>> 15, t | 1); t ^= t + Math.imul(t ^ t >>> 7, t | 61); return ((t ^ t >>> 14) >>> 0) / 4294967296; };
  const resize = () => { W = innerWidth; H = innerHeight; dpr = Math.min(devicePixelRatio || 1, 2); canvas.width = Math.floor(W*dpr); canvas.height = Math.floor(H*dpr); canvas.style.width = W+'px'; canvas.style.height = H+'px'; ctx.setTransform(dpr,0,0,dpr,0,0); floorY=H-68; if(player && player.grounded) player.y=floorY-player.h; };
  addEventListener('resize', resize); resize();
  const makeLevel = () => {
    platforms = [
      {x:0,w:760,height:0},{x:835,w:590,height:0},{x:1515,w:760,height:0},{x:2385,w:915,height:0},
      {x:435,w:145,height:105},{x:945,w:170,height:125},{x:1165,w:120,height:70},{x:1620,w:160,height:105},{x:1865,w:180,height:145},{x:2110,w:150,height:90},{x:2530,w:155,height:120},{x:2750,w:170,height:78}
    ];
    enemies = [
      {x:420,home:420,min:340,max:620,hp:2,type:'wretch',dir:1},{x:680,home:680,min:610,max:740,hp:2,type:'wretch',dir:-1},
      {x:1020,home:1020,min:880,max:1110,hp:2,type:'wretch',dir:1},{x:1320,home:1320,min:1190,max:1390,hp:3,type:'knight',dir:-1},
      {x:1690,home:1690,min:1550,max:1800,hp:2,type:'wretch',dir:1},{x:2040,home:2040,min:1900,max:2210,hp:3,type:'knight',dir:-1},
      {x:2510,home:2510,min:2410,max:2630,hp:2,type:'wretch',dir:1},{x:2700,home:2700,min:2620,max:2810,hp:3,type:'knight',dir:-1}
    ].map(e=>({...e,maxHp:e.hp,vy:0,grounded:false,hurt:0,attack:0,dead:false}));
    relics = [760,1510,2370].map((x,i)=>({x,y:floorY-[125,175,135][i],got:false,bob:rand(i+8)*6}));
    projectiles=[]; particles=[];
    boss={x:3040,y:floorY-92,w:58,h:92,hp:14,maxHp:14,active:false,dead:false,dir:-1,attack:1.2,hurt:0,vy:0};
  };
  const reset = () => { makeLevel(); savedRelics=0; checkpoint=100; player={x:100,y:floorY-58,w:34,h:58,vx:0,vy:0,dir:1,hp:5,maxHp:5,soul:35,grounded:false,invuln:0,dash:0,dashCd:0,attackCd:0,spellCd:0,anim:0}; updateHud(); };
  reset();
  const updateHud = () => {
    ui.hearts.innerHTML=Array.from({length:player.maxHp},(_,i)=>`<span class="heart ${i>=player.hp?'empty':''}">♥</span>`).join('');
    ui['soul-fill'].style.width=Math.min(100,player.soul)+'%';ui.relics.textContent=savedRelics;
  };
  const showToast = (text,duration=2300) => { ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=duration; };
  const start = () => { if(mode==='title'){ mode='play'; ui['title-screen'].hidden=true; ui.hud.hidden=false; showToast('VESPERIA · Los jardines hundidos',2600); } else if(mode==='lore'){ui['lore-screen'].hidden=true;mode='play';} };
  document.getElementById('begin-button').onclick=start;
  document.getElementById('lore-title-button').onclick=()=>{mode='lore';ui['lore-screen'].hidden=false;};
  document.getElementById('lore-continue').onclick=()=>{ui['lore-screen'].hidden=true;if(mode==='title')mode='title';else mode='play';};
  document.getElementById('pause-button').onclick=()=>togglePause();
  document.getElementById('resume-button').onclick=()=>togglePause(false);
  document.getElementById('pause-lore').onclick=()=>{ui['pause-screen'].hidden=true;ui['lore-screen'].hidden=false;mode='lore';};
  document.getElementById('lore-button').onclick=()=>{if(mode==='play'){mode='lore';ui['lore-screen'].hidden=false;}};
  document.getElementById('again-button').onclick=()=>{reset();ui['ending-screen'].hidden=true;ui.hud.hidden=false;mode='play';showToast('UNA NUEVA VIGILIA COMIENZA',2000);};
  const togglePause=(force)=>{if(force===false||mode==='pause'){mode='play';ui['pause-screen'].hidden=true;}else if(mode==='play'){mode='pause';ui['pause-screen'].hidden=false;}};
  const keyMap={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',Space:'jump',ArrowUp:'jump',KeyW:'jump',KeyJ:'attack',KeyX:'attack',KeyK:'dash',KeyC:'dash',KeyL:'spell',KeyV:'spell',Escape:'pause'};
  const just = new Set();
  addEventListener('keydown',e=>{const a=keyMap[e.code];if(a){e.preventDefault();if(!keys.has(a))just.add(a);keys.add(a);if(a==='pause')togglePause();if(mode==='title'&&a==='jump')start();}});
  addEventListener('keyup',e=>{const a=keyMap[e.code];if(a)keys.delete(a);});
  document.querySelectorAll('.touch-controls button').forEach(button=>{
    const action=button.dataset.action, key=button.dataset.key;
    const down=e=>{e.preventDefault();button.classList.add('pressed');if(key){actions[key]=true;}else{just.add(action);keys.add(action);}};
    const up=e=>{e.preventDefault();button.classList.remove('pressed');if(key)actions[key]=false;else keys.delete(action);};
    button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);
  });
  const isDown=a=>keys.has(a)||actions[a];
  const inRange=(a,b,range)=>Math.abs(a-b)<range;
  const burst=(x,y,color,n=8)=>{for(let i=0;i<n;i++){let ang=Math.random()*Math.PI*2,s=20+Math.random()*110;particles.push({x,y,vx:Math.cos(ang)*s,vy:Math.sin(ang)*s-25,life:.45+Math.random()*.55,max:.9,color,size:1+Math.random()*3});}};
  const damagePlayer=(amount=1)=>{if(player.invuln>0||player.dash>0||mode!=='play')return;player.hp-=amount;player.invuln=1.05;player.vx=-player.dir*220;player.vy=-180;shake=9;burst(player.x+player.w/2,player.y+player.h/2,'#d87563',12);updateHud();if(player.hp<=0){player.hp=player.maxHp;player.soul=Math.max(0,player.soul-15);player.x=checkpoint;player.y=floorY-player.h;player.vx=player.vy=0;showToast('La ceniza te devuelve al último santuario.',2600);updateHud();}};
  const strike=()=>{if(player.attackCd>0)return;player.attackCd=.36;slashTimer=.19;slashHit.clear();player.soul=Math.min(100,player.soul+2);burst(player.x+player.w/2+player.dir*22,player.y+29,'#e2ca91',4);};
  const castSpell=()=>{if(player.spellCd>0||player.soul<35)return;player.soul-=35;player.spellCd=.7;projectiles.push({x:player.x+player.w/2+player.dir*24,y:player.y+player.h*.48,vx:player.dir*390,life:1.25,from:'player'});burst(player.x+player.w/2,player.y+player.h/2,'#9bcec2',7);updateHud();};
  const hurtEnemy=(enemy,damage=1)=>{if(enemy.dead||enemy.hurt>0)return;enemy.hp-=damage;enemy.hurt=.27;enemy.vx=player.dir*140;player.soul=Math.min(100,player.soul+14);burst(enemy.x+17,enemy.y+25,'#d18468',8);if(enemy.hp<=0){enemy.dead=true;player.soul=Math.min(100,player.soul+9);burst(enemy.x+17,enemy.y+22,'#d0ad73',14);}updateHud();};
  const hurtBoss=(damage=1)=>{if(boss.dead||boss.hurt>0)return;boss.hp-=damage;boss.hurt=.3;boss.vx=player.dir*85;player.soul=Math.min(100,player.soul+9);shake=5;burst(boss.x+boss.w/2,boss.y+40,'#dc8669',14);if(boss.hp<=0){boss.dead=true;setTimeout(()=>{if(mode==='play'){mode='ending';ui.hud.hidden=true;ui['ending-screen'].hidden=false;}},850);}updateHud();};
  const attackCheck=()=>{if(slashTimer<=0)return;let cx=player.x+player.w/2+player.dir*39,cy=player.y+player.h*.52;for(const e of enemies){if(!e.dead&&!slashHit.has(e)&&Math.abs(e.x+17-cx)<48&&Math.abs(e.y+27-cy)<49){slashHit.add(e);hurtEnemy(e);}}if(boss.active&&!boss.dead&&Math.abs(boss.x+boss.w/2-cx)<65&&Math.abs(boss.y+boss.h/2-cy)<65&&!slashHit.has(boss)){slashHit.add(boss);hurtBoss(1);}};
  const update=(dt)=>{
    if(mode!=='play')return;elapsed+=dt;if(toastTimer>0){toastTimer-=dt*1000;if(toastTimer<=0)ui.toast.classList.remove('show');}if(slashTimer>0)slashTimer-=dt;player.anim+=dt*9;player.invuln=Math.max(0,player.invuln-dt);player.attackCd=Math.max(0,player.attackCd-dt);player.spellCd=Math.max(0,player.spellCd-dt);player.dashCd=Math.max(0,player.dashCd-dt);
    const move=(isDown('right')?1:0)-(isDown('left')?1:0);if(move)player.dir=move;
    if(just.has('jump')&&player.grounded){player.vy=-470;player.grounded=false;burst(player.x+player.w/2,floorY,'#c4b391',4);}
    if(just.has('attack'))strike();if(just.has('spell'))castSpell();if(just.has('dash')&&player.dashCd<=0){player.dash=.18;player.dashCd=.72;player.vx=player.dir*570;player.vy=0;burst(player.x+player.w/2,player.y+player.h/2,'#c7aa72',8);}
    if(player.dash>0){player.dash=Math.max(0,player.dash-dt);player.vy=0;}else{player.vx+=(move*700-player.vx)*Math.min(1,dt*11);player.vy+=1250*dt;}
    player.x+=player.vx*dt;player.y+=player.vy*dt;player.x=Math.max(0,Math.min(WORLD-player.w,player.x));player.grounded=false;
    for(const p of platforms){const py=floorY-p.height;if(player.x+player.w>p.x&&player.x<p.x+p.w&&player.y+player.h>=py&&player.y+player.h-player.vy*dt<=py+12&&player.vy>=0){player.y=py-player.h;player.vy=0;player.grounded=true;}}
    if(player.y+player.h>=floorY){player.y=floorY-player.h;player.vy=0;player.grounded=true;}
